{
  "bioavailability_prediction": "low",
  "claims": [
    {
      "card_ids": ["C01"],
      "claim": "Peramivir, a highly polar, ionizable antiviral with multiple H-bond donors/acceptors, has oral bioavailability <3% in humans; the query shares high polarity, extensive H-bonding, and ionizable amine character, supporting low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C27"],
      "claim": "Perindoprilat, the polar active acid metabolite of perindopril, has oral bioavailability of 19±7% in young healthy subjects, below the 20% threshold; the query is similarly a polar, non-prodrug molecule with multiple H-bonding groups, supporting low F.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C32"],
      "claim": "Brivaracetam has almost 100% oral bioavailability and is the highest-similarity analogue, but it is a small neutral lactam lacking the query's polar thioglycoside and extensive H-bond donor array, so its high-F result has limited transferability.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C17"],
      "claim": "Perindopril has about 75% oral bioavailability, but this reflects an ester prodrug masking a polar carboxylic acid; the query is not such a prodrug and retains multiple free polar groups, so this high-F evidence is weakly transferable.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "Predicted low oral bioavailability (<20%) because the query is a highly polar, ionizable thioglycoside-like molecule with multiple H-bond donors/acceptors and unfavorable passive permeability. The most threshold-relevant transferable evidence—peramivir (<3%) and perindoprilat (~19%)—supports low F, while high-F analogues either lack the polar sugar or rely on prodrug masking.",
  "evidence_gaps": [
    "No direct human PK data exist for the query or a close thioglycoside analogue.",
    "Morgan similarities to all evidence molecules are low (<0.23), limiting structural transferability.",
    "Potential roles of active uptake, efflux transport, or metabolic first-pass extraction are not experimentally characterized.",
    "Formulation or prodrug strategies that could alter oral bioavailability are unknown for the query."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

